source_raw_tex:
\eqalign{\liminf_{n\to\infty}a_n
&=\sup_{n\in\Bbb N}\inf_{\lower 0.4ex\hbox{$\scriptstyle m\ge n$}}a_m
=\sup_{n\in\Bbb N}(-\sup_{m\ge n}(-a_m))\cr
&=-\inf_{\lower 0.4ex\hbox{$\scriptstyle n\in\Bbb N$}}
     \sup_{m\ge n}(-a_m)
=-\limsup_{n\to\infty}(-a_n).\cr}

target_raw_tex:
\eqalign{\liminf_{n\to\infty}a_n
&=\sup_{n\in\Bbb N}\inf_{\lower 0.4ex\hbox{$\scriptstyle m\ge n$}}a_m
=\sup_{n\in\Bbb N}(-\sup_{m\ge n}(-a_m))\cr
&=-\inf_{\lower 0.4ex\hbox{$\scriptstyle n\in\Bbb N$}}
     \sup_{m\ge n}(-a_m)
=-\limsup_{n\to\infty}(-a_n).\cr}
